def test_r7_multiple_patterns_are_supported(tmp_path):
    _make_files(tmp_path, ["a.csv", "b.csv"])
    _make_files(tmp_path, ["c.json"])
    result = task_func(os.path.join(str(tmp_path), "*.csv"))
    basenames = {os.path.basename(m) for m in _archive_members(result)}
    assert {"a.csv", "b.csv"} <= basenames
    assert os.path.isfile(os.path.join(str(tmp_path), "c.json"))

def _make_files(directory, names, content="data"):
    os.makedirs(directory, exist_ok=True)
    paths = []
    for name in names:
        path = os.path.join(directory, name)
        with open(path, "w") as f:
            f.write(content)
        paths.append(path)
    return paths

def _member_basenames(archive_path):
    return {os.path.basename(name.rstrip("/")) for name in _archive_members(archive_path)}

def test_r4_archive_contains_matched_files(tmp_path):
    _make_files(str(tmp_path), ["a.txt", "b.txt"])
    result = task_func(os.path.join(str(tmp_path), "*.txt"))
    assert _member_basenames(result) == {"a.txt", "b.txt"}

