def test_r9_multiple_patterns_are_independent(tmp_path):
    _make_files(str(tmp_path), ["x.txt", "y.txt"])
    _make_files(str(tmp_path), ["z.md"])
    result = task_func(os.path.join(str(tmp_path), "*.md"))
    assert _member_basenames(result) == {"z.md"}
    assert os.path.isfile(os.path.join(str(tmp_path), "x.txt"))
    assert os.path.isfile(os.path.join(str(tmp_path), "y.txt"))
